function renderPlan(data){renderConcept(data);$('build-explanation').textContent=data.explanation||data.features.join('. ');list('build-decisions',[...(data.corrections||[]),...(data.decisions||['Deine gespeicherten Maße und Materialien.'])]);list('build-features',data.features);list('build-supplies',data.supplies.map(p=>p.name+' · '+p.material+' · '+p.size.map(n=>Number(n.toFixed(1))).join(' × ')+' mm'));list('build-steps',data.steps);renderGuide();list('build-tools',data.tools);list('build-days-list',data.schedule.map(s=>'Tag '+s.day+': '+s.task));$('build-limits').textContent=data.limits;const links=$('build-shops');links.replaceChildren();for(const [name,query]of [['Platten / Zuschnitt',data.supplies[0].material+' Zuschnitt '+data.spec.width+' mm'],['Verbinder','Montagewinkel Schrauben '+data.supplies[0].material],...(data.parts.some(p=>p.material==='light')?[['LED & Diffusor','5V USB LED Modul Diffusor Platte']]:[])]){const a=document.createElement('a');a.textContent=name+' ↗';a.href='https://www.google.com/search?q='+encodeURIComponent(query);a.target='_blank';a.rel='noopener noreferrer';links.append(a);} }
function conversationContext(text){const part=model.parts.find(p=>p.id===selected);if(part&&/ausgewählt|bauteil|dieses teil/i.test(text))return {title:model.title,part,features:model.features,limits:model.limits};const systems=model.concept?.systems||[],chosen=systems.find(s=>text.toLocaleLowerCase().includes(s.name.toLocaleLowerCase()));return chosen?{title:model.title,system:chosen,unresolved:model.concept.unresolved.slice(0,3).map(t=>t.slice(0,150))}:{title:model.title,explanation:model.explanation,spec:model.spec,parts:model.parts.slice(0,4).map(p=>({name:p.name,shape:p.shape,material:p.material,size:p.size})),features:model.features};}
async function submit(text){text=text.trim().replace(/^(?:jarvis|astra)[, :]+/i,'').replace(/[.!?]+$/,'');if(/^(?:stopp?|abbrechen)[.! ]*$/i.test(text)){stop();status('Gestoppt.');return;}if(/übernimm|uebernimm|entscheide du|plane du|mach du/i.test(text))$('build-auto').checked=true;if(controller){queuedText=text.slice(0,1000);message('assistant','Dein neuester Wunsch ist vorgemerkt. Ich übernehme ihn direkt nach diesem Schritt. Mit Stopp verwirfst du ihn.');return;}if(!text.trim()&&!model){status('Beschreibe zuerst deinen Bauwunsch. Es wird kein Musterobjekt gebaut.');return;}if(!text.trim())text='';if(text)message('user',text);if(/^(?:stopp?|abbrechen)[.! ]*$/i.test(text)){stop();status('Gestoppt.');return;}if(/(?:was kann|was bringt|wie funktioniert)/i.test(text)&&model){const reply='Sir, '+(model.explanation||model.features.join('. '))+'. '+model.limits;message('assistant',reply);say(reply);return;}if(/wo.*(?:kauf|find|bauteil)|einkauf|materialliste/i.test(text)&&model){const reply='Die Teile mit Maßen stehen unter „Material & Einkauf“. Die Suchlinks öffnen passende Suchanfragen; Preise und Lagerbestand sind noch nicht geprüft.';message('assistant',reply);say(reply);$('build-shopping').open=true;return;}if(/anleitung|wie baue|wie mache|^(?:weiter|nächster schritt|zurück)[.! ]*$/i.test(text)&&model){$('build-guide').open=true;setBuildView('guide');if(/^weiter|^nächster/i.test(text))guideStep=Math.min(guideStep+1,model.steps.length-1);if(/^zurück/i.test(text))guideStep=Math.max(0,guideStep-1);renderGuide();const reply='Schritt '+(guideStep+1)+' von '+model.steps.length+': '+model.steps[guideStep];message('assistant',reply);say(reply);return;}if(/wie (?:lange|schnell)|zeitplan|zeitfenster/i.test(text)&&model){$('build-timetable').open=true;const reply='Dein Zeitfenster sind '+model.spec.days+' Tage. Die Aufteilung daneben ist ein Vorschlag, keine garantierte Bauzeit. Beginne mit dem Pappmodell und dem Zuschnitt.';message('assistant',reply);say(reply);return;}if(/wo.*pass|wie groß|wie gross/i.test(text)&&model){const reply='Die Außenmaße sind '+model.spec.width+' × '+model.spec.height+' × '+model.spec.depth+' mm. Miss deinen Standort aus und prüfe Platz für Kabel, Bedienung und die Montage.';message('assistant',reply);say(reply);return;}if(model&&/^(?:warum|welch|was empfiehlst|wie findest|kannst du erklären|erklär|erzähl|ich verstehe|ich habe eine frage)/i.test(text)){const c=new AbortController();controller=c;const timer=setTimeout(()=>c.abort(),60000);try{const reply=await api('/api/device-ai/chat',{text:'Erkläre als Jarvis verständlich den tatsächlichen Vorentwurf. Keine behaupteten Änderungen oder Statikfreigaben. Entwurf: '+JSON.stringify(conversationContext(text)).slice(0,1000)+'. Frage: '+text.slice(0,700),history:history.slice(0,-1),mode:'jarvis'},c.signal);if(panel.open&&controller===c){message('assistant',reply.reply);say(reply.reply);}}catch(e){if(panel.open)message('assistant',e.name==='AbortError'?'Gespräch gestoppt.':e.message);}finally{clearTimeout(timer);if(controller===c){controller=null;runQueued();}}return;}

 const c=new AbortController();controller=c;$('build-starts').open=false;lastDiagnostic='';$('build-error-details').hidden=true;$('build-submit').disabled=true;setBuildView('model');status('Deine lokale KI entwickelt den eigenen 3D-Entwurf …');let expired=false;const timer=setTimeout(()=>{expired=true;c.abort();},300000);try{const combinedBrief=pendingBrief?pendingBrief+'\nAntwort / Ergänzung: '+text:text;const data=await designJob({spec:spec(),request:combinedBrief,automatic:$('build-auto').checked,free_design:true,regenerate:!!pendingBrief,...(model?{previous:{brief:model.brief||'',spec:model.spec,title:model.title,parts:model.parts,steps:model.steps,features:model.features,...(model.concept?{concept:model.concept}:{}),...(model.explanation?{explanation:model.explanation}:{})}}:{})},c);if(!panel.open||controller!==c)return;if(data.needs_details){pendingBrief=combinedBrief;const question=data.questions.join(' ');message('assistant',question);status('Jarvis hat eine Rückfrage. Antworte hier oder per Sprache.');say(question);return;}pendingBrief='';await showModel(data);if(controller!==c)return;message('assistant',data.reply);say(data.reply);}catch(e){if(panel.open&&controller===c){const error=e.name==='AbortError'?(expired?'Die lokale KI braucht zu lange. Der Auftrag wurde gestoppt; dein bisheriger Entwurf bleibt erhalten.':'Entwurf gestoppt.'):e.message;message('assistant',error);if(e.name!=='AbortError'&&!lastDiagnostic)recordDiagnostic(error);status(model?'Der bisherige Entwurf bleibt erhalten.':'Es wurde noch kein Entwurf erstellt. Fehlerdetails stehen unten.');}}finally{clearTimeout(timer);if(controller===c){controller=null;$('build-submit').disabled=false;runQueued();}else if(!controller)$('build-submit').disabled=false;}}
function runQueued(){if(queuedText&&panel.open&&!controller){const text=queuedText;queuedText=null;queueMicrotask(()=>submit(text));}}
function stop(){stopMusic();panel.dataset.work='idle';if(activeJob){cancelJob(activeJob);activeJob=null;}pendingBrief='';queuedText=null;if(assemblyRunning)$('build-canvas').dataset.assembly='stopped';cancelMotion();controller?.abort();controller=null;epoch++;$('build-submit').disabled=false;}
function stopVoice(){duckMusic(false);voiceEpoch++;audioSource?.stop();audioSource=null;speaking=false;voicePlaying=false;}
async function say(t){if(!$('build-read').checked||!audioCtx){listen();return;}const v=++voiceEpoch;audioSource?.stop();audioSource=null;voicePlaying=false;speaking=true;recognition?.abort();try{if(!token)await api('/api/workshop/design',{spec:spec(),request:''});const r=await fetch('/api/natural-voice/speak',{method:'POST',headers:{'Content-Type':'application/json','X-Jarvis-Token':token},body:JSON.stringify({text:t.slice(0,650),preset:'jarvis'})});if(!r.ok)throw Error('Thorsten ist am verbundenen Mac nicht verfügbar.');const buffer=await audioCtx.decodeAudioData(await r.arrayBuffer());if(v!==voiceEpoch||!panel.open)return;audioSource=audioCtx.createBufferSource();audioSource.buffer=buffer;audioSource.connect(audioCtx.destination);audioSource.onended=()=>{if(v===voiceEpoch){speaking=false;voicePlaying=false;duckMusic(false);listen();}};audioSource.start();voicePlaying=true;duckMusic(true);}catch(e){if(v===voiceEpoch){speaking=false;$('build-voice-status').textContent=e.message;status(e.message);listen();}}}
function listen(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!listening||recognition||speaking||!panel.open)return;if(!Recognition){listening=false;$('build-voice-status').textContent='Dieser Browser unterstützt keine Spracherkennung. Texteingabe funktioniert weiterhin.';return;}const r=new Recognition();recognition=r;r.lang='de-DE';r.interimResults=false;r.continuous=false;r.onresult=e=>{const t=e.results[0][0].transcript;$('build-request').value=t;submit(t);};r.onstart=()=>{if(!panel.open){r.abort();return;}micActive=true;};r.onend=()=>{if(recognition===r){recognition=null;micActive=false;}if(listening&&!speaking)setTimeout(listen,400);};r.onerror=e=>{if(['not-allowed','audio-capture','service-not-allowed'].includes(e.error)){listening=false;$('build-voice-status').textContent='Mikrofon nicht verfügbar. Du kannst schreiben.';}};try{r.start();$('build-voice-status').textContent='Jarvis hört zu. Änderungen werden ohne Senden übernommen.';}catch(_){recognition=null;listening=false;}}
function stopListening(){listening=false;micActive=false;recognition?.abort();recognition=null;stopVoice();$('build-talk').textContent='Mit Jarvis sprechen';$('build-voice-status').textContent='Mikrofon aus.';}
function saveFile(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let musicCtx=null,musicGain=null,musicTimer=null,musicStop=null,musicPads=[];
function duckMusic(talking){if(musicCtx&&musicGain)musicGain.gain.setTargetAtTime(talking?.12:.65,musicCtx.currentTime,.15);}
function stopMusic(){clearInterval(musicTimer);clearTimeout(musicStop);musicTimer=musicStop=null;for(const node of musicPads){try{node.stop();}catch(_){}}musicPads=[];if(musicCtx){musicCtx.close().catch(()=>{});musicCtx=null;musicGain=null;}if(panel)panel.dataset.music='off';}
async function startMusic(){if(!$('build-music')?.checked||musicCtx||!panel.open)return;let ctx=null;try{ctx=new(window.AudioContext||window.webkitAudioContext)();musicCtx=ctx;await ctx.resume();if(musicCtx!==ctx){ctx.close().catch(()=>{});return;}musicGain=ctx.createGain();musicGain.gain.value=voicePlaying?.12:.65;musicGain.connect(ctx.destination);for(const frequency of [55,82.4069]){const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=frequency;g.gain.value=.012;o.connect(g);g.connect(musicGain);o.start();musicPads.push(o);}let step=0;const notes=[110,164.8138,220,164.8138,130.8128,196,261.6256,196];musicTimer=setInterval(()=>{if(musicCtx!==ctx)return;const o=ctx.createOscillator(),g=ctx.createGain(),now=ctx.currentTime;o.type='triangle';o.frequency.value=notes[step++%notes.length];g.gain.setValueAtTime(0,now);g.gain.linearRampToValueAtTime(.012,now+.08);g.gain.exponentialRampToValueAtTime(.0001,now+.65);o.connect(g);g.connect(musicGain);o.start(now);o.stop(now+.7);},550);musicStop=setTimeout(stopMusic,45000);panel.dataset.music='playing';}catch(_){if(!ctx||musicCtx===ctx){stopMusic();status('Musik bitte über „Musik beim Entwerfen“ per Klick aktivieren.');}}}
let face=null,faceRAF=null,faceLast=0,micActive=false;
function paintFace(t){if(!face||face.hidden||!panel.open||document.hidden)return;const state=voicePlaying?'speaking':controller||speaking||assemblyRunning?'working':micActive?'listening':listening?'connecting':'idle';face.dataset.state=state;$('build-face-state').textContent=({speaking:'Thorsten spricht',working:'Jarvis arbeitet',listening:'Ich höre dir zu',connecting:'Mikrofon startet …',idle:'Bereit für deine Idee'})[state];if(window.JarvisOrb)window.JarvisOrb.draw($('build-face-canvas'),t,{speaking:voicePlaying,working:state==='working'});}
function startFace(){if(!face||face.hidden||faceRAF!==null||!panel.open||document.hidden)return;function loop(t){if(!panel.open||document.hidden||face.hidden){faceRAF=null;return;}faceRAF=requestAnimationFrame(loop);if(t-faceLast<50)return;faceLast=t;paintFace(t);}faceRAF=requestAnimationFrame(loop);}
function stopFace(){if(faceRAF!==null)cancelAnimationFrame(faceRAF);faceRAF=null;faceLast=0;}
function createFace(){face=document.createElement('section');face.id='build-companion';face.dataset.motion='on';face.setAttribute('aria-label','Schwebender Jarvis-Helfer im Browser');face.innerHTML='<div id="build-face-grip" title="Im Browser verschieben">⠿ JARVIS <button id="build-face-hide" type="button" aria-label="Gesicht ausblenden und Mikrofon stoppen">−</button></div><canvas id="build-face-canvas" width="240" height="240" aria-label="Jarvis-Gesicht, das beim Sprechen den Mund bewegt"></canvas><small id="build-face-state" role="status">Bereit für deine Idee</small><div class="build-face-actions"><button id="build-face-talk" type="button" aria-label="Mit Jarvis sprechen">🎙</button><button id="build-face-mute" type="button" aria-label="Nur Jarvis-Stimme stoppen">◼</button><button id="build-face-motion" type="button" aria-label="Bewegung umschalten" aria-pressed="true">↝</button></div>';panel.append(face);const restore=document.createElement('button');restore.id='build-face-restore';restore.type='button';restore.textContent='◉ Jarvis zeigen';restore.hidden=true;panel.append(restore);import('/jarvis-orb.js').then(()=>{paintFace(performance.now());startFace();}).catch(()=>{$('build-face-state').textContent='Gesicht nicht geladen. Die Werkstatt bleibt nutzbar.';});$('build-face-talk').onclick=()=>$('build-talk').click();$('build-face-mute').onclick=()=>$('build-mute').click();$('build-face-motion').onclick=()=>{const on=face.dataset.motion!=='on';face.dataset.motion=on?'on':'off';$('build-face-motion').setAttribute('aria-pressed',String(on));};$('build-face-hide').onclick=()=>{stopListening();face.hidden=true;restore.hidden=false;stopFace();};restore.onclick=()=>{face.hidden=false;restore.hidden=true;startFace();};let dragging=null;const grip=$('build-face-grip');grip.onpointerdown=e=>{if(e.target.closest('button'))return;const r=face.getBoundingClientRect();dragging={x:e.clientX-r.left,y:e.clientY-r.top};face.dataset.motion='off';$('build-face-motion').setAttribute('aria-pressed','false');face.style.transform='none';face.style.left=r.left+'px';face.style.top=r.top+'px';face.style.right='auto';face.style.bottom='auto';grip.setPointerCapture(e.pointerId);};grip.onpointermove=e=>{if(!dragging)return;const r=panel.getBoundingClientRect();face.style.left=Math.max(r.left+6,Math.min(r.right-face.offsetWidth-6,e.clientX-dragging.x))+'px';face.style.top=Math.max(r.top+6,Math.min(r.bottom-face.offsetHeight-6,e.clientY-dragging.y))+'px';};grip.onpointerup=grip.onpointercancel=()=>dragging=null;}
function create(){const style=document.createElement('link');style.rel='stylesheet';style.href='/workshop.css';document.head.append(style);panel=document.createElement('dialog');panel.id='build-studio';panel.setAttribute('aria-label','Jarvis 3D-Baustudio');panel.innerHTML=`<header class="build-head"><div><small>JARVIS / WERKSTATT</small><h2>Von deiner Idee zum Bauteil.</h2><p>Grauer Modellierbereich · Material und Farbe stehen in deiner Anleitung</p></div><button id="build-close">Schließen ×</button></header><div class="build-layout"><section class="build-view"><div class="build-view-head"><strong id="build-title">Dein 3D-Baustudio</strong><span>MODELL / DREHEN & ANTIPPEN</span></div><canvas id="build-canvas" aria-label="Interaktiver 3D-Bauentwurf" width="740" height="500"></canvas><p id="build-status" role="status">Beschreibe deinen Bauwunsch. Sage später auch einfach: Das gefällt mir nicht – neuer Entwurf.</p><label>Einzelteile auseinanderziehen <input id="build-explode" type="range" min="0" max="1" step="0.02" value="0"></label><p id="build-part">Die Teile zeigen dieselben Maße wie die Materialliste.</p><div class="build-chat" id="build-chat" aria-live="polite"></div><details id="build-error-details" hidden><summary>Fehlerdetails – zum Weitergeben</summary><p>Enthält die Fehlermeldung und Programmversion, keine Beschreibung deines Bauwunschs und keinen Chatverlauf.</p><pre id="build-error-text"></pre><button type="button" id="build-error-copy">Fehlerdetails kopieren</button></details><form id="build-form"><label>Wunsch oder Änderung<textarea id="build-request" maxlength="1000" rows="2" placeholder="Beschreibe dein Objekt, seine Funktion und gewünschte Details. Zum Beispiel: ein geschwungener Ständer mit Kabelöffnung aus schwarzem Holz."></textarea></label><div class="build-actions"><button id="build-submit">Entwurf bauen / ändern</button><button id="build-stop" type="button">Stoppen</button></div></form><details id="build-speech-settings"><summary>Sprache & Mikrofon</summary><p>Browser-Spracherkennung kann Audio online verarbeiten. Sie beginnt erst mit deiner Zustimmung.</p><label><input id="build-speech-consent" type="checkbox"> Browser-Spracherkennung erlauben</label><label><input id="build-read" type="checkbox" checked> Mit Thorsten antworten</label><button id="build-talk">Mit Jarvis sprechen</button><button id="build-mute">Reden stoppen</button><p id="build-voice-status" role="status">Mikrofon aus.</p></details></section><aside class="build-controls"><h3>Dein eigener Entwurf.</h3><label class="build-auto-label"><input id="build-auto" type="checkbox" checked> Jarvis schlägt Material und Maße vor</label><p class="build-muted">Beschreibe das gewünschte Objekt. Deine lokale KI entwickelt Konturen und Bauteile daraus – ohne automatische Auswahl einer Bauvorlage.</p><button id="build-delegate" type="button" disabled>Entwurf nach meinem Wunsch überarbeiten ↗</button><details id="build-manual"><summary>Maße und Material selbst vorgeben</summary><input id="build-template" type="hidden" value="custom"><label>Material<select id="build-material"><option value="wood">Holz / Sperrholz</option><option value="metal">Metallblech</option><option value="plastic">Kunststoffplatte</option></select></label><div class="build-dimensions"><label>Breite · mm<input id="build-width" type="number" min="0.1" max="1200" value="240"></label><label>Höhe · mm<input id="build-height" type="number" min="0.1" max="1200" value="180"></label><label>Tiefe · mm<input id="build-depth" type="number" min="0.1" max="1200" value="100"></label><input id="build-thickness" type="hidden" value="12"></div><label>Dein Zeitfenster · Tage<input id="build-days" type="number" min="1" max="30" value="3"></label><p class="build-muted">Deine Angaben sind Vorgaben für den Entwurf. Die kleine lokale KI kann Details falsch verstehen; prüfe Modell und Anleitung vor dem Bauen.</p></details><div id="build-result" hidden><section class="build-decision-card"><small>MEINE ENTSCHEIDUNGEN</small><p id="build-explanation"></p><ul id="build-decisions"></ul></section><details id="build-concept" hidden><summary>Baugruppen & Funktion · Konzept</summary><p class="build-muted">Funktionsidee mit offenen Prüfpunkten. Bewegung, Belastbarkeit und Steuerung sind noch nicht simuliert oder getestet.</p><div id="build-systems"></div><h4>Vorgesehener Funktionsablauf</h4><ol id="build-workflow"></ol><h4>Noch technisch zu klären</h4><ul id="build-unresolved"></ul></details><details open><summary>Was es kann</summary><ul id="build-features"></ul></details><details open id="build-shopping"><summary>Material & Einkauf</summary><ul id="build-supplies"></ul><div id="build-shops"></div><p class="build-muted">Suchlinks · keine geprüften Preise oder Bestände. Verbindungsmittel kommen zusätzlich zu den dargestellten Platten hinzu.</p></details><details id="build-guide"><summary>Bauanleitung & Werkzeug</summary><ol id="build-steps"></ol><ul id="build-tools"></ul></details><details id="build-timetable"><summary>Vorschlag für deine Bautage</summary><ol id="build-days-list"></ol></details><p id="build-limits" class="build-muted"></p><button id="build-save">Entwurf auf diesem Gerät sichern</button><button id="build-load">Gesicherten Entwurf laden</button><button id="build-export">Bauplan als Text herunterladen</button></div></aside></div>`;document.body.append(panel);$('build-error-copy').onclick=async()=>{try{await navigator.clipboard.writeText(lastDiagnostic);$('build-error-copy').textContent='Kopiert';}catch(_){$('build-error-details').open=true;const range=document.createRange();range.selectNodeContents($('build-error-text'));const selection=getSelection();selection.removeAllRanges();selection.addRange(range);$('build-error-copy').textContent='Text markieren und kopieren';}};const savedButton=$('build-load');savedButton.textContent='Gesicherten Entwurf anzeigen';savedButton.disabled=true;panel.querySelector('.build-controls').insertBefore(savedButton,$('build-result'));const tabs=document.createElement('nav');tabs.className='build-view-tabs';tabs.innerHTML='<button type="button" data-build-view="model" aria-pressed="true">◈ 3D-Modell</button><button type="button" data-build-view="guide" aria-pressed="false" disabled>▤ Anleitung direkt ansehen</button><button type="button" id="build-replay" disabled>▷ Montage abspielen</button><label>Ansicht <select id="build-style"><option value="solid">Modell</option><option value="hologram">Hologramm</option></select></label><label><input type="checkbox" id="build-wire"> Drahtgitter</label><label><input type="checkbox" id="build-led-toggle" checked disabled> LED-Vorschau</label><label><input type="checkbox" id="build-led-xray" checked disabled> LED-Innenansicht</label><label><input type="checkbox" id="build-music"> Musik beim Entwerfen</label>';const view=panel.querySelector('.build-view'),pane=document.createElement('div');pane.id='build-model-pane';const canvas=$('build-canvas');canvas.before(tabs,pane);for(const el of [canvas,$('build-status'),$('build-explode').closest('label'),$('build-part')])pane.append(el);const guide=document.createElement('section');guide.id='build-guide-pane';guide.hidden=true;guide.innerHTML='<div id="build-reflector-size" hidden><label>Große Öffnung · mm<input id="build-reflector-width" type="number" min="40" max="160" value="60"></label><label>Kleine Öffnung · mm<input id="build-reflector-opening" type="number" min="4" max="30" value="10"></label><button id="build-reflector-recalculate" type="button">Maße neu berechnen</button></div><button type="button" id="build-test-motif" hidden>Vierfaches Testmotiv öffnen</button><h3>Deine Bauanleitung</h3><p id="build-inline-finish"></p><ol id="build-inline-steps"></ol><p>Schritte antippen zum Vorlesen. Du kannst auch „weiter“ oder „zurück“ sagen.</p>';const ledInfo=document.createElement('p');ledInfo.id='build-led-summary';ledInfo.className='build-muted';ledInfo.textContent='LEDs werden angezeigt, wenn sie zum Entwurf gehören.';pane.append(ledInfo);const info=document.createElement('p');info.id='build-part-info';info.hidden=true;const ask=document.createElement('button');ask.id='build-ask-part';ask.type='button';ask.hidden=true;ask.textContent='Mit Jarvis über dieses Teil sprechen';ask.onclick=()=>{const part=model?.parts.find(p=>p.id===selected);if(part)submit('Erkläre mir das ausgewählte Bauteil '+part.name+' und seine mögliche Funktion.');};const inspector=document.createElement('section');inspector.id='build-inspector';inspector.hidden=true;inspector.setAttribute('aria-label','Ausgewähltes 3D-Bauteil');const closeInfo=document.createElement('button');closeInfo.id='build-inspector-close';closeInfo.type='button';closeInfo.textContent='×';closeInfo.setAttribute('aria-label','Teilinfo schließen');closeInfo.onclick=()=>inspector.hidden=true;inspector.append(closeInfo,info,ask);pane.append(inspector);pane.after(guide);$('build-reflector-recalculate').onclick=()=>openProject({base:Number($('build-reflector-width').value),opening:Number($('build-reflector-opening').value)}).catch(e=>status(e.message));$('build-test-motif').onclick=()=>openMotif();$('build-style').onchange=()=>setSurfaceMode($('build-style').value);$('build-music').onchange=()=>{$('build-music').checked?startMusic():stopMusic();};$('build-led-toggle').onchange=updateLEDs;$('build-led-xray').onchange=updateLEDs;for(const b of tabs.querySelectorAll('[data-build-view]'))b.onclick=()=>setBuildView(b.dataset.buildView);$('build-wire').onchange=()=>{for(const mesh of meshes)mesh.material.wireframe=$('build-wire').checked;draw();};$('build-replay').onclick=async()=>{if(!model||controller||assemblyRunning)return;setBuildView('model');await showModel(model);};const projectButton=document.createElement('button');projectButton.id='build-hologram-project';projectButton.type='button';projectButton.textContent='Hologramm-Gerät selbst bauen';projectButton.onclick=()=>openProject().catch(e=>status(e.message));panel.querySelector('.build-view-head').before(projectButton);const starts=document.createElement('details');starts.id='build-starts';starts.innerHTML='<summary>Startideen · oder deine eigene Idee</summary>';for(const [title,goal]of [['Lichtobjekt','Eine geschwungene Tischlampe mit LED und stabilem Fuß'],['Möbel','Ein platzsparendes Möbel mit Ablage und verstecktem Kabelkanal'],['Organizer','Ein Schreibtisch-Organizer mit verschieden großen Fächern'],['Skulptur','Eine Skulptur aus Ringen und Kugeln mit sichtbarer Halterung'],['Gehäuse','Ein Gehäuse für ein kleines Elektronikprojekt mit Lüftungsöffnungen']]){const b=document.createElement('button');b.type='button';b.textContent=title;b.onclick=()=>{starts.open=false;$('build-request').value=goal;$('build-request').focus();};starts.append(b);}panel.querySelector('.build-view-head').before(starts);const brief=$('build-form');panel.querySelector('.build-view').prepend(brief);$('build-request').rows=1;$('build-submit').textContent='Jarvis, mach das';$('build-delegate').onclick=()=>{ $('build-auto').checked=true;submit('Erstelle einen neuen Entwurf für meinen bisherigen Bauwunsch. Entwickle einen anderen Aufbau und eigene Konturen. Behalte meine bisherigen Anforderungen bei.');};for(const k of fields)$('build-'+k).addEventListener('change',()=>{$('build-auto').checked=false;});createFace();$('build-close').onclick=()=>panel.close();panel.addEventListener('close',()=>{stopMusic();stop();stopListening();stopFace();});panel.addEventListener('cancel',stop);$('build-stop').onclick=()=>{stop();status('Montage / Anfrage gestoppt.');};$('build-form').onsubmit=e=>{e.preventDefault();submit($('build-request').value);};$('build-explode').oninput=explode;$('build-material').onchange=()=>{$('build-thickness').value={wood:12,metal:2,plastic:5}[$('build-material').value];};$('build-speech-consent').onchange=()=>{if(!$('build-speech-consent').checked)stopListening();};$('build-talk').onclick=async()=>{if(listening){stopListening();return;}if(!$('build-speech-consent').checked){$('build-voice-status').textContent='Bitte zuerst der Browser-Spracherkennung zustimmen.';$('build-speech-settings').open=true;$('build-speech-consent').focus();return;}try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();}catch(_){}listening=true;$('build-talk').textContent='Zuhören beenden';listen();};$('build-mute').onclick=()=>{stopVoice();$('build-read').checked=false;listen();};$('build-save').onclick=async()=>{try{await DeviceStore.set('jarvis-workshop-v1',model);status('Entwurf auf diesem Gerät gespeichert.');$('build-load').disabled=false;}catch(e){status(e.message);}};$('build-load').onclick=async()=>{try{const saved=await DeviceStore.get('jarvis-workshop-v1');if(!saved)throw Error('Hier ist noch kein Entwurf gesichert.');await showModel(saved);status('Gesicherten Entwurf geladen. Änderungen brauchen den verbundenen Mac.');}catch(e){status(e.message);}};$('build-export').onclick=()=>{if(model)saveFile('Jarvis-Bauplan.txt',model.title+'\n\n'+JSON.stringify(model.spec,null,2)+'\n\nMaterial:\n'+model.supplies.map(p=>p.name+' · '+p.material+' · '+p.size.join(' × ')+' mm').join('\n')+'\n\nBauanleitung:\n'+model.steps.map((t,i)=>(i+1)+'. '+t).join('\n')+'\n\n'+model.limits,'text/plain;charset=utf-8');};document.addEventListener('visibilitychange',()=>{if(document.hidden){stopMusic();stopListening();stopFace();}else{draw();if(panel.open)startFace();}});}
export async function open(request='',{draftOnly=false,viewMode}={}){if(!panel)create();if(!panel.open)panel.showModal();if(viewMode)setSurfaceMode(viewMode);startFace();if(request)$('build-request').value=request;if(request&&!draftOnly)await submit(request);else if(!model){let saved;try{saved=await window.DeviceStore?.get('jarvis-workshop-v1');}catch(_){}try{init3D();setSurfaceMode(surfaceMode);draw();status(saved?'Arbeitsbereich bereit. Ein gesicherter Entwurf ist vorhanden; du kannst ihn ausdrücklich anzeigen oder einen neuen Wunsch beschreiben.':'Arbeitsbereich bereit. Beschreibe, was Jarvis für dich entwerfen soll.');if(saved)$('build-load').disabled=false;}catch(_){status('Für die 3D-Ansicht wird WebGL benötigt.');}}else draw();}

export async function openProject(dimensions={}){await open();const data=await api('/api/workshop/hologram-project',dimensions);await showModel(data);message('assistant',data.reply);setBuildView('guide');}

function openMotif(){const d=document.createElement('dialog');d.style.cssText='padding:12px;background:black;color:white;border:1px solid #4f6;max-width:96vw';const c=document.createElement('canvas');c.width=c.height=600;c.style.cssText='display:block;width:min(80vw,70vh);height:auto;background:black';const close=document.createElement('button');close.textContent='Testmotiv schließen';close.onclick=()=>d.close();d.append(c,close);document.body.append(d);d.showModal();let frame=null;const ctx=c.getContext('2d');function draw(t){if(!d.open)return;ctx.fillStyle='black';ctx.fillRect(0,0,600,600);for(let i=0;i<4;i++){ctx.save();ctx.translate(300,300);ctx.rotate(i*Math.PI/2);ctx.translate(0,-160);ctx.strokeStyle='#79ffe2';ctx.lineWidth=3;ctx.beginPath();const a=t*.0005;for(let n=0;n<5;n++){const angle=n*Math.PI/2+a,x=Math.cos(angle)*40,y=Math.sin(angle)*40;if(!n)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.stroke();ctx.restore();}frame=requestAnimationFrame(draw);}frame=requestAnimationFrame(draw);d.addEventListener('close',()=>{cancelAnimationFrame(frame);d.remove();});}
